# 入队
def enqueue(data, x, front, rear):
    if rear == len(data):
        raise OverflowError("队满")
    data[rear] = x
    return front, rear + 1

# 出队
def dequeue(data, front, rear):
    if front == rear:
        raise IndexError("队空")
    x = data[front]
    return x, front + 1, rear

class ArrayQueue:
    def __init__(self, cap):
        self.data = [None] * cap
        self.front = 0
        self.rear = 0

    def is_empty(self):
        return self.front == self.rear

    def is_full(self):
        return self.rear == len(self.data)

    def enqueue(self, x):
        if self.is_full():
            raise OverflowError("队满")
        self.data[self.rear] = x
        self.rear += 1

    def dequeue(self):
        if self.is_empty():
            raise IndexError("队空")
        x = self.data[self.front]
        self.front += 1
        return x

q = ArrayQueue(3)
q.enqueue(1); q.enqueue(2); q.enqueue(3)
print(q.dequeue(), q.dequeue())  # 1 2
print(q.is_empty(), q.is_full())  # False True
